node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check specs and compatible_with more closely
const row = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-2028EE'\").get();
console.log('Full product row:', JSON.stringify(row, null, 2));

// Check if there are any related tables with compatibility info
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('\nAll tables:', tables.map(t => t.name));

// Check for any compatibility or specs tables
for (const t of tables) {
    if (t.name.includes('compat') || t.name.includes('spec') || t.name.includes('feature')) {
        console.log('\nTable', t.name, ':', db.prepare('SELECT * FROM ' + t.name + ' LIMIT 5').all());
    }
}
"
